//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ЕСТЬNULL(ВТ_ИтоговаяТаблица.Объект, "") КАК ОбъектУстановки, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик, "") КАК Счетчик, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик.Код, "") КАК СсылочныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ПочтовыйАдрес, "") КАК АдресДома, ЕСТЬNULL(бит_Счетчики.ЗаводскойСерийныйНомерПУ, "") КАК ЗаводскойСерийныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУ, "") КАК ВидПУ, ЕСТЬNULL(бит_Счетчики.МаркаПУ, "") КАК МаркаПУ, ЕСТЬNULL(бит_Счетчики.МодельПУ, "") КАК МодельПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.УникальныйНомерДома, "") КАК УникальныйНомерДома, ЕСТЬNULL(ВТ_ИтоговаяТаблица.УникальныйНомерПомещения, "") КАК УникальныйНомерПомещения, ЕСТЬNULL(ВТ_ИтоговаяТаблица.УникальныйНомерКомнаты, "") КАК УникальныйНомерКомнаты, ЕСТЬNULL(ВТ_ИтоговаяТаблица.НомерЛС, "") КАК НомерЛС, ВЫБОР КОГДА бит_Счетчики.ДистанционноеСнятиеПоказаний = ЗНАЧЕНИЕ(Перечисление.ДаНет.Нет) ТОГДА "нет" КОГДА бит_Счетчики.ДистанционноеСнятиеПоказаний = ЗНАЧЕНИЕ(Перечисление.ДаНет.Да) ТОГДА "да" ИНАЧЕ "" КОНЕЦ КАК ДистанционноеСнятиеПоказаний, ЕСТЬNULL(бит_Счетчики.НаименованияУстановленнойСистемы, "") КАК НаименованияУстановленнойСистемы, "нет" КАК ОбъемНесколькихПриборовУчета, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидКоммунальногоРесурса, "") КАК ВидКоммунальногоРесурса, ЕСТЬNULL(КлассификаторЕдиницИзмерения.НаименованиеПолное, "") КАК ЕдиницаИзмерения, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУПоКоличествуТарифов, "") КАК ВидПУПоКоличествуТарифов, ЕСТЬNULL(ВТ_ИтоговаяТаблица.БазовоеПоказаниеТ1, 0) КАК БазовоеПоказаниеТ1, ВЫБОР КОГДА ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУПоКоличествуТарифов, "") = "Двухтарифный" ИЛИ ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУПоКоличествуТарифов, "") = "Трехтарифный" ТОГДА ЕСТЬNULL(ВТ_ИтоговаяТаблица.БазовоеПоказаниеТ2, 0) ИНАЧЕ "" КОНЕЦ КАК БазовоеПоказаниеТ2, ВЫБОР КОГДА ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУПоКоличествуТарифов, "") = "Трехтарифный" ТОГДА ЕСТЬNULL(ВТ_ИтоговаяТаблица.БазовоеПоказаниеТ3, 0) ИНАЧЕ "" КОНЕЦ КАК БазовоеПоказаниеТ3, ВЫБОР КОГДА ЕСТЬNULL(бит_Счетчики.КоэффициентТрансформации, 0) = 0 ТОГДА "" ИНАЧЕ ЕСТЬNULL(бит_Счетчики.КоэффициентТрансформации, "") КОНЕЦ КАК КоэффициентТрансформации, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ДатаУстановки, ДАТАВРЕМЯ(1, 1, 1)) КАК ДатаУстановки, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ДатаВводаВЭксплуатацию, ДАТАВРЕМЯ(1, 1, 1)) КАК ДатаВводаВЭксплуатацию, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ДатаПоследнейПоверки, ДАТАВРЕМЯ(1, 1, 1)) КАК ДатаПоследнейПоверки, ЕСТЬNULL(бит_Счетчики.ДатаОпломбированияЗаводом, ДАТАВРЕМЯ(1, 1, 1)) КАК ДатаОпломбированияЗаводом, ЕСТЬNULL(ПРЕДСТАВЛЕНИЕ(бит_Счетчики.МежповерочныйИнтервал), "") КАК МежповерочныйИнтервал, ВЫБОР КОГДА бит_Счетчики.НаличиеДатчиковТемпературы = ЗНАЧЕНИЕ(Перечисление.ДаНет.Нет) ТОГДА "нет" КОГДА бит_Счетчики.НаличиеДатчиковТемпературы = ЗНАЧЕНИЕ(Перечисление.ДаНет.Да) ТОГДА "да" ИНАЧЕ "" КОНЕЦ КАК НаличиеДатчиковТемпературы, ЕСТЬNULL(бит_Счетчики.ИнформацияДатчиковТемпературы, "") КАК ИнформацияДатчиковТемпературы, ВЫБОР КОГДА бит_Счетчики.НаличиеДатчиковДавления = ЗНАЧЕНИЕ(Перечисление.ДаНет.Нет) ТОГДА "нет" КОГДА бит_Счетчики.НаличиеДатчиковДавления = ЗНАЧЕНИЕ(Перечисление.ДаНет.Да) ТОГДА "да" ИНАЧЕ "" КОНЕЦ КАК НаличиеДатчиковДавления, ЕСТЬNULL(бит_Счетчики.ИнформацияДатчиковДавления, "") КАК ИнформацияДатчиковДавления, "нет" КАК АвтоматическийРасчетОбъема ИЗ ВТ_ИтоговаяТаблица КАК ВТ_ИтоговаяТаблица ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Счетчики КАК бит_Счетчики ПО ВТ_ИтоговаяТаблица.Счетчик = бит_Счетчики.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Справочник.КлассификаторЕдиницИзмерения КАК КлассификаторЕдиницИзмерения ПО ВТ_ИтоговаяТаблица.ЕдИзм = КлассификаторЕдиницИзмерения.Ссылка
